using System;

namespace StdbModule;

public static partial class RussianQuotes
{
    public static class АндрейБелый
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Ещё, и ещё в синюю бездну дня, полную жарких, жестоких блесков, кинула зычные блики целебеевская колокольня.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "А душный от благовонья Троицын день обсыпал кусты лёгкими, розовыми шиповниками.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "И жар душил грудь; в жаре стекленели стрекозиные крылья над прудом, взлетали в жар в синюю бездну дня, — туда, в голубой покой пустынь.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Славное село Целебеево, подгородное; средь холмов оно да лугов; туда, сюда раскидалось домишками, прибранными богато, то узорной резьбой, точно лицо заправской модницы в кудряшках, то петушком из крашеной жести, то размалёванными цветиками, ангелочками; славно оно разукрашено плетнями, садочками, а то и смородинным кустом, и целым роем скворечников, торчащих в заре на согнутых метлах своих: славное село!", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Дарьяльский сызмальства прослыл чудаком, но, говорят, такое прошёл учёное заведение, где с десяток мудрейших особ из года в год невесть на каких языках неприличнейшего сорта стишки вместо наук разбирать изволят — ей-Богу!", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "И охотник же был Дарьяльский до такого сорта стишков, и сам в них преуспевал; писал обо всём: и о белолилейной пяте, и о мирре уст, и даже… о полиелее ноздрей.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Но, спрошу я, какая такая разница между богиней и бабой? Богиня ли, баба ли — всё одно: кем же, как не бабами, в древности сами богини были.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "— Да ты сообрази, дубовое твоё рыло, — сообрази ты: кто над землёй трудится? Мужик — я, чай! Мужику и земля, тоись, в полное апчественное обладание.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "В борьбе обретёшь ты право своё!", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Бысть ветер буйный, и занесе меня в кобак; и рекл ми целовальник: «Человече, чего хощеши?» И отвещах ему: «Зелья водошнаго».", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Едва они въехали в Лихов, как стали подпрыгивать, да так, будто под тележку были нарочно подброшены самые что ни на есть неудобомостимые камни.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Мы вышли на станцию, бросивши взгляд на зубчатые стены; топорщилась башня желтеющим кубом; чернели разъятою пастью ворота, где бледно змеилась дорожка неясных бурнусов, сквозь клубы вихряемой пыли; стояли мечи минаретов среди приподнявшихся чалм куполов; и казалось: вздрогнет Европа, и — новый Медхи опрокинется бурей бурнусов в ветшающий днями, в облупленный мир: в мир Европы.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "…я боюсь — будет час; кровь с огромною силой прильет к голове организма французской Европы, — кровь черная: миллионами негров, мулатов вдруг хлынет в Париж, Марсель, Гавр, Лион, — Африка, так, что жилы страны разорвутся, под мощным напором; и европейскую Францию быстро постигнет удар: почернеет её голова; и в XXIII столетии будет Париж переполнен курчавыми толпами чёрных «чертей»: парижан!", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "…Европа — «юнеет»: Европа — «мулатится», собираясь «онегриться»; пока ещё что только милые негритёнки — апаши шалят себе в древнем Париже; и то ли ещё мы увидим — в текущем столетии: вероятно, увидим мы скоро оазис Сахары — «юнеющей» Франции — в городских, крупных центрах: в Париже, в Марселе, в Лионе, в Бордо; вероятно бэбэ, именуемые апашами, пожелают продеть себе кольца в носы и облечься, согласно инстинкту, в звериные шкуры; и, может быть, разовьются в песчаный оазис — со скачущим туарегом, фалангой и коброю.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "За столами писцы; на стол приходится пара их; перед каждым: перо и чернила и почтенная стопка бумаг; писец по бумаге поскрипывает, переворачивает листы, листом шелестит и пером верещит (думаю, что зловещее растение «вереск» происходит от верещания); так ветер осенний, невзгодный, который заводят ветра ― по лесам, по оврагам; так и шелест песка ― в пустырях, в солончаковых пространствах ― оренбургских, самарских, саратовских...", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "На стене красовался зелёный кудреватый шпинат, рисовавший зигзагами плезиры петергофской натуры с пространствами, облаками и с сахарным куличом в виде стильного павильончика.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Выходили в зал из передней какие-то ангелоподобные существа в голубых, белых, розовых платьях, серебристые, искристые; обвевали газами, веерами, шелками, разливая вокруг благодатную атмосферу фиалочек, ландышей, лилий и тубероз; слегка опылённые пудрой их мраморно-белые плечики через час, через два должны были разгореться румянцем и покрыться испариной; но теперь, перед танцами, личики, плечи и худые обнаженные руки казались ещё бледней и худей, чем в обычные дни; тем значительней прелесть этих существ как-то сдержанно искрами занималась в зрачках, пока существа, сущие ангелята, образовали и шелестящие и цветные рои веющей кисеи; свивались и развивались их белые веера, производя лёгкий ветер; топотали их туфельки.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Над суровым, дубовым столом лысая голова не напружилась височными жилами; не глядела она исподлобья туда, где в камине текли резвой стаей васильки угарного газа: в одинокой той комнате всё же праздно в камине текли огоньки угарного газа над калёною грудою растрещавшихся угольков; разрывались там, отрывались и рвались ― красные петушиные гребни, пролетая стремительно в дымовую трубу, чтоб сливаться над крышами с гарью, с отравленной копотью и бессменно над крышами повисать удушающей, разъедающей мглой.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "С. М., весьма оскорблённый в своем романтизме увидеть идею «не только» поэзии в ряде годин, не мог слышать о Блоке, слагая пародии на «глубину».", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Он скрежещет кривою улыбкой; лицо очень бледное, старообразное; жёлтая пара; как камень шершавый, с которого жёлтенький лютик растёт; так конфузлив, как листья растения «не-тронь-меня»; чуть что ― ёжится: нет головы; лицом ― в плечи; лишь лысинка!", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Я же нагнулся в лорнетóчный блеск Зинаиды «Прекрасной» и взял пахнущую туберозою ручку под синими блёсками спрятанных глаз; удлинённое личико, коль глядеть сбоку; и маленькое — с фасу: от вздёрга под нос подбородка; совсем неправильный нос.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Дмитрий Сергеич — оранжерейный, утончённый «попик», воздвигший молеленку среди духов туберозы, гаванских сигар; видом — постник: всос щёк, строго-выпуклые, водянистые очи; душою — чиновник, а духом — капризник и чувственник; субъективист — до мизинца; кричал он об общине, а падал в обмороки от звонков, проносясь в кабинет, — от поклонников, сбывши их Гиппиус; отпрепарировав, взяв за ручку, их Гиппиус вела в кабинетище...", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Рогами гранными, как чёрт, Туда — в века, в лазури-ляпис — Граниторозовый простёрт В неё влюблённый, странный Апис.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "И бросят в арфы, — шали, шарфы, Вздыхая вестью дорогой, — Вон те, Марии, эти Марфы, Над жизнью, старою каргой.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Соединив четыре силы В троякой были глубиной, Меня примите из могилы, Светите оком — Той, Одной, — Мечтой вуалевой, как трепет, Несущей далевую жизнь На печальный мой лепет Сквозь звуков маревую жизнь.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Мои мистические дали Смычком взвивались заливным, Смычком плаксивым и родным — Смычком профессора Гржимали: Он под Василием Ильичом (Расставив ноги калачом), — Который, — — чаля из эонов На шар земной, — объятый тьмой, Рукою твёрдой на тромбонах Плывет назад — в Москву, домой:", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Двадцатилетием таимый, Двадцатилетием чернён, Я слышу зов многолюбимый Сегодня, Троицыным днём, — И под берёзкой кружевною, Простёртой доброю рукой, Я смыт вздыхающей волною В неутихающий покой.", Author = "Андрей Белый" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "В 1904 году Андрей Белый был ещё очень молод, золотокудр, голубоглаз и в высшей степени обаятелен.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Газетная подворотня гоготала над его стихами и прозой, поражавшими новизной, дерзостью, иногда — проблесками истинной гениальности.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "В его присутствии всё словно мгновенно менялось, смещалось или озарялось его светом.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "И он в самом деле был светел.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Кажется, все, даже те, кто ему завидовал, были немножко в него влюблены.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Малую правду, свою человеческую, просто человеческую любовь они рядили в одежды правды неизмеримо большей.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Так играли словами, коверкая смыслы, коверкая жизни.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Впоследствии исковеркали жизнь и самой Жене, облечённой в Солнце, и мужу её, одному из драгоценнейших русских поэтов.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Так играли словами, коверкая смыслы, коверкая жизни.", Author = "Владислав Ходасевич" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Из поэтов-символистов следующие четыре поэта писали больше всего по философским вопросам: Андрей Белый, Вячеслав Иванов, Н.М. Минский и Д.С. Мережковский.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Андрей Белый рассматривает символизм как мировоззрение, составляющее основу символистического искусства и воплощающего «некоторые черты таоизма в реалистическом миросозерцании».", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Символизм есть синтез Индии, Персии, Египта, Греции и средних веков.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Точные науки не объясняют мир как целое: они 'ограничивают' предмет познания и тем самым «систематизируют отсутствие познания».", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Жизнь раскрывается не через научное познание, а через творческую деятельность, которая «недоступна анализу, интегральна и всемогущественна».", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Она только может быть выражена в символических образах, облекающих идею.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Единство жизни выражается такими символами, как Адам Кадмон из каббалы, Атман из индийской философии, Логос-Христос.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "В целом философия Андрея Белого есть разновидность пантеизма.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "В процессе познавательного или творческого 'символизирования' символ становится реальностью.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Живое слово тесно связано с реальностью и поэтому получает магическую силу.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Поэзия, говорит Андрей Белый, связана с творением слов – дар, которым он сам обладал в изумительной степени.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Некоторые из слов, придуманные им, следовало бы ввести во всеобщее употребление, но другие выражают такие неуловимые и быстротечные нюансы того предмета, который он изображает, что их можно использовать только раз в жизни.", Author = "Николай Лосский" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Мне поручили написать отзыв о только что вышедшей книге стихов А. Белого.", Author = "Тэффи" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Это была какая-то неожиданная некрасовщина, гражданская скорбь и гражданское негодование, столь Белому несвойственное, что некоторые места её казались прямо пародией.", Author = "Тэффи" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Да, нет сомнения, что в годы короткой передышки между двумя революциями и двумя войнами, в десятилетие от года 1905 до года 1915, Россия переживала весьма знаменательный культурный подъём.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "В Москве, в которой жил тогда Белый и на фоне которой помню его, шла большая, горячая и подлинно творческая духовная работа.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Протекала она не только в узком кругу передовой интеллигенции, но захватывала и весьма широкие слои.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "В эти годы московской жизни Андрей Белый с одинаковой почти страстностью бурлил и пенился на гребнях всех её волн.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Он бывал и выступал на всех заседаниях «Религиозно-философского общества»; в «Литературно-художественном кружке» и в «Свободной эстетике» воевал против писателей-натуралистов; под общим заглавием «На перевале» писал в «Весах» свои запальчивые статьи то против мистики, то против музыки; редактировал коллективный дневник «Мусагета» под названием «Труды и дни»; бывал у Скрябиных, Метнеров и д'Альгеймов, увлекаясь вагнеровской идеей синтетического театрального действа.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Перечислить всё, над чем тогда думал и чем мучился, о чём спорил и против чего неистовствовал в своих выступлениях Белый, решительно невозможно.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Его сознание подслушивало и отмечало всё, что творилось в те канунные годы как в русской, так и в мировой культуре.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Недаром он сам себя охотно называл сейсмографом.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Но чего бы ни касался Белый, он, в сущности, всегда волновался одним и тем же — всеохватывающим кризисом европейской культуры и жизни.", Author = "Фёдор Степун" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Андрей_Белый", Text = "Все его публичные выступления твердили об одном и том же: о кризисе культуры, о грядущей революции, о горящих лесах и о расползающихся в России оврагах.", Author = "Фёдор Степун" },
        };
    }
